use super::*;

/// The `@keyframes` NAME for a def — namespaced by `component` when one resolves (#3163).
pub(crate) fn keyframe_name(component: &str, kit: &str, name: &str) -> String {
    let seg = ident_segment(component);
    if seg.is_empty() {
        format!("bsc-{kit}-{name}")
    } else {
        format!("bsc-{kit}-{seg}-{name}")
    }
}
